transitions.transitionKernelCode:
const position = input.SapReorderSignal[0].units;
const gap = Math.max(0, parameters.sonaflozin_target - position);
const increment = Math.max(1, parameters.sonaflozin_order_increment);
const units = Math.ceil(gap / increment) * increment;
return {
  SonaflozinOrdered: [{ units, remaining_weeks: parameters.placeholder_sonaflozin_supplier_weeks }],
  PurchaseCostCommitted: [{ eur: units * parameters.chinese_sonaflozin_eur_per_unit }]
};

const lot = input.SonaflozinInTransit[0];
return {
  SonaflozinQuarantine: [{ units: lot.units, remaining_weeks: lot.remaining_weeks }],
  SonaflozinReceivedUnits: [{ units: lot.units }]
};

transitions.lambdaCode:
const needed = input.ProductionOrderWaiting[0].units;
const sonaflozin = input.SonaflozinReleased[0];
const flowbind = input.FlowbindAvailable[0];
return needed > 0 && sonaflozin.remaining_weeks > 0 && flowbind.remaining_weeks > 0 && sonaflozin.units >= needed && flowbind.units >= needed;

transitions.transitionKernelCode:
const needed = input.ProductionOrderWaiting[0].units;
const sonaflozin = input.SonaflozinReleased[0];
const flowbind = input.FlowbindAvailable[0];
return {
  SonaflozinReleased: [{ units: sonaflozin.units - needed, remaining_weeks: sonaflozin.remaining_weeks }],
  FlowbindAvailable: [{ units: flowbind.units - needed, remaining_weeks: flowbind.remaining_weeks }],
  SonicFlowBatchProduced: [{ units: needed, age_weeks: 0 }]
};

transitions.lambdaCode:
const order = input.CustomerOrdersWaiting[0];
const lot = input.SonicFlowBatchProduced[0];
return order.units > 0 && order.weeks_to_due >= 0 && lot.units >= order.units && lot.age_weeks < parameters.example_finished_life_weeks;

transitions.transitionKernelCode:
const order = input.CustomerOrdersWaiting[0].units;
const lot = input.SonicFlowBatchProduced[0];
return {
  SonicFlowBatchProduced: [{ units: lot.units - order, age_weeks: lot.age_weeks }],
  SonicFlowShipped: [{ units: order }]
};

const units = parameters.flowbind_german_topup_units;
return {
  GermanFlowbindTopUpOrdered: [{ units, remaining_weeks: parameters.placeholder_new_flowbind_supplier_weeks }],
  PurchaseCostCommitted: [{ eur: units * parameters.german_flowbind_eur_per_unit }],
  GermanSwitchCostEvents: [{ eur: parameters.estimated_german_switch_eur }]
};

const units = parameters.flowbind_german_topup_units;
return {
  GermanFlowbindTopUpOrdered: [{ units, remaining_weeks: parameters.placeholder_new_flowbind_supplier_weeks }],
  PurchaseCostCommitted: [{ eur: units * parameters.german_flowbind_eur_per_unit }],
  GermanSwitchCostEvents: [{ eur: parameters.estimated_german_switch_eur }]
};

const lot = input.GermanFlowbindTopUpOrdered[0];
return {
  FlowbindQuarantine: [{ units: lot.units, remaining_weeks: lot.remaining_weeks }],
  FlowbindReceivedUnits: [{ units: lot.units }]
};

transitions.lambdaCode:
const order = input.CustomerOrdersWaiting[0];
const lot = input.SonicFlowBatchProduced[0];
return order.is_contract && order.weeks_to_due < 0 && order.units > 0 && lot.units >= order.units && lot.age_weeks < parameters.example_finished_life_weeks;

transitions.transitionKernelCode:
const order = input.CustomerOrdersWaiting[0];
const lot = input.SonicFlowBatchProduced[0];
return {
  SonicFlowBatchProduced: [{ units: lot.units - order.units, age_weeks: lot.age_weeks }],
  ContractOrdersShippedLate: [{ units: order.units }]
};

const position = input.FlowbindSapPositionReading[0].units;
const gap = Math.max(0, parameters.flowbind_target - position);
const increment = Math.max(1, parameters.flowbind_order_increment);
const units = Math.ceil(gap / increment) * increment;
return {
  IndianFlowbindOnOrder: [{ units, remaining_weeks: parameters.placeholder_new_indian_supplier_weeks }],
  PurchaseCostCommitted: [{ eur: units * parameters.indian_flowbind_eur_per_unit }]
};

const lot = input.IndianFlowbindOnOrder[0];
return {
  FlowbindQuarantine: [{ units: lot.units, remaining_weeks: lot.remaining_weeks }],
  FlowbindReceivedUnits: [{ units: lot.units }]
};

metrics.code:
const late = state.places.ContractOrdersShippedLate.count;
const cancelled = state.places.SpotOrdersCancelled.count;
const overdue = state.places.CustomerOrdersWaiting.tokens.filter(order => order.weeks_to_due < 0).length;
return late + cancelled + overdue;

